import os
import subprocess
import sys
import unittest

from boltons.csvrecords import read_records


CUR_PATH = os.path.dirname(os.path.abspath(__file__))
REPO_ROOT = os.path.dirname(CUR_PATH)
EXAMPLE_PATH = os.path.join(REPO_ROOT, 'examples', 'csvrecords.py')


class ReadRecordsTest(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(read_records('a,b\n1,2\n3,4\n'),
                         [{'a': '1', 'b': '2'}, {'a': '3', 'b': '4'}])

    def test_values_are_strings(self):
        records = read_records('a,b\n1,2.5\n')
        self.assertEqual(records, [{'a': '1', 'b': '2.5'}])
        for value in records[0].values():
            self.assertIsInstance(value, str)

    def test_header_only(self):
        self.assertEqual(read_records('a,b\n'), [])

    def test_empty_document(self):
        self.assertEqual(read_records(''), [])

    def test_no_trailing_newline(self):
        self.assertEqual(read_records('a,b\n1,2'), [{'a': '1', 'b': '2'}])

    def test_crlf(self):
        self.assertEqual(read_records('a,b\r\n1,2\r\n'), [{'a': '1', 'b': '2'}])

    def test_quoted_comma(self):
        records = read_records('name,note\n"Doe, Jane","hi, there"\n')
        self.assertEqual(records, [{'name': 'Doe, Jane', 'note': 'hi, there'}])

    def test_multiline_field(self):
        records = read_records('id,text\n1,"line one\nline two"\n')
        self.assertEqual(records, [{'id': '1', 'text': 'line one\nline two'}])

    def test_duplicate_headers(self):
        with self.assertRaises(ValueError):
            read_records('a,a\n1,2\n')

    def test_duplicate_headers_any_row(self):
        with self.assertRaises(ValueError):
            read_records('a,b,a\n1,2,3\n')

    def test_row_too_short(self):
        with self.assertRaises(ValueError):
            read_records('a,b\n1\n')

    def test_row_too_long(self):
        with self.assertRaises(ValueError):
            read_records('a,b\n1,2,3\n')

    def test_single_column(self):
        self.assertEqual(read_records('a\n1\n2\n'),
                         [{'a': '1'}, {'a': '2'}])

    def test_document_with_single_field_rows(self):
        # A document whose rows each have a single field is fine.
        self.assertEqual(read_records('a\n\n'), [])


class ExampleCommandTest(unittest.TestCase):
    def _run(self, payload):
        proc = subprocess.run([sys.executable, EXAMPLE_PATH],
                              input=payload, capture_output=True, text=True,
                              cwd=REPO_ROOT)
        return proc

    def test_success(self):
        proc = self._run(json.dumps(['a,b\n1,2\n']) + '\n')
        self.assertEqual(proc.returncode, 0)
        self.assertEqual(proc.stdout, json.dumps([{'a': '1', 'b': '2'}]) + '\n')
        self.assertEqual(proc.stderr, '')

    def test_error_is_nonzero_and_silent(self):
        proc = self._run(json.dumps(['a,b\n1\n']) + '\n')
        self.assertNotEqual(proc.returncode, 0)
        self.assertEqual(proc.stdout, '')

    def test_multiple_lines_continue_after_error(self):
        payload = (json.dumps(['a,b\n1\n']) + '\n'
                   + json.dumps(['a,b\n1,2\n']) + '\n')
        proc = self._run(payload)
        self.assertNotEqual(proc.returncode, 0)
        self.assertEqual(proc.stdout, json.dumps([{'a': '1', 'b': '2'}]) + '\n')


if __name__ == '__main__':
    unittest.main()
